 */
scwin.btn_popRelLawDtl_onclick = function(e){
    try {
        fn_popRelLawDtl()  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_popRelLawDtl — as-is 정의 없음(원본 JS 미제공 — 회신)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf72000.btn_popRelLawDtl_onclick' }); }
};

/**
 * @method
 * @name tx_onpageload
 * @description tx 페이지 로드 이벤트
 * @returns {Promise<void>}
