 */
scwin.tx_onpageload = async function () {
    try {
        const sbmOptions = {
            id: "tx_onpageload",
            method: "post",
            action: "",
            ref: "dma_searchRelLawReq",
            target: "dlt_resultList=body",
            isProcessMsg: false
        };
        return await $c.sbm.executeDynamic(sbmOptions);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf72000.tx_onpageload" });
    }
};

/**
 * @method
 * @name __on_enter_2_ipt_searchtext
 * @description on enter 2 ipt searchtext 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_2_ipt_searchtext = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchRelLaw() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf72000.__on_enter_2_ipt_searchText' }); }
};

/**
