 */
scwin.krxpage_pagenavigator_62_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_loadListReq').set('pageIndex', pi);
        await scwin.tx_load_list();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf72000.krxpage_pagenavigator_62_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchRelLaw
 * @description search Rel Law 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchRelLaw = async function () {
    const sbmOptions = {
        id: "tx_fn_searchRelLaw",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_searchRelLawReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_detail
 * @description detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_detail = async function () {
    const sbmOptions = {
        id: "tx_fn_detail",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_detailReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_loadListReq",
        target: "dlt_junmoonList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["pageCount"] != null ? rj["pageCount"] : (rj.body && rj.body["pageCount"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_62").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
