    const url = "/ods/integsrchBase.do?method=updateRelLaw&SCREN_ID=JLDSTF72010.jsp&SCREN_PROCES_TP_CD=01&relLawNo=" + relLawNo;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "popup", type: "pageFramePopup", title: "관련법규조항 변경", width: "1200px", height: "800px" }, {});
};

