    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "popup", type: "pageFramePopup", title: "관련법규조항 등록", width: "1200px", height: "800px" }, {});
};

/**
 * @method
 * @name openSTF73000
 * @description open STF73000 처리
