 * @hidden N
 */
scwin.openSTF73000 = function () {
    const url = "/ods/integsrchBase.do?method=searchRelLawDtlRegList&SCREN_ID=JLDSTF73000.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "popup", type: "pageFramePopup", title: "단위조항", width: "1200px", height: "800px" }, {});
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name detailDone
 * @description detail Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.detailDone = function (data) {
    (($c.util.getComponent('mappIntegSrch')) && ($c.util.getComponent('mappIntegSrch')).removeAll ? ($c.util.getComponent('mappIntegSrch')).removeAll() : (($c.util.getComponent('mappIntegSrch')) && ($c.util.getComponent('mappIntegSrch')).setValue ? ($c.util.getComponent('mappIntegSrch')).setValue('') : void 0)).append(data);
    makeTableOdd();
};

/**
 * @method
 * @name detail
 * @description detail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.detail = async function () {
    const r = await scwin.tx_fn_detail();
    try {
